from pathlib import Path
import json
tid='DEV-PRED-ASTRA-RESULT-NORMALIZE-R6-20261008-N1E140'
roots=[Path.home()/'.local/state/prediction-project-executor', Path.home()/'.local/share/prediction-project-executor']
hits=[]
for root in roots:
    if not root.exists(): continue
    for p in root.rglob('*'):
        if tid not in p.name: continue
        if p.is_file():
            try: txt=p.read_text(errors='replace')
            except Exception: continue
            hits.append((str(p),txt[:6000]))
print('ERROR_CLASS=N1E140_STATE_PROBE')
if not hits:
    print('ERROR=NO_MATCHING_LOCAL_STATE')
else:
    flat=[]
    for path,txt in hits[:20]:
        s=txt.replace('\n',' ').replace('\r',' ').replace('|','/').replace('{','(').replace('}',')')
        flat.append('PATH='+path+' DATA='+s[:1200])
    print('ERROR='+' || '.join(flat))
raise SystemExit(1)
